const path = 'research/artifacts/xyflow/0a1f9575b25679f2880175de8d3eae21aedde921/packages/react/src/utils/changes.ts'
const source = await Bun.file(path).text()
const start = source.indexOf('function applyChanges(')
const end = source.indexOf('\n/**', source.indexOf('function applyChange('))
const extracted = source.slice(start, end)
const compiled = new Bun.Transpiler({ loader: 'ts' }).transformSync(extracted)
const apply = new Function(`${compiled}; return applyChanges;`)()
const item = { id: '1', position: { x: 0, y: 0 }, measured: { width: 100, height: 40 }, style: { width: 200, height: 100 } }
const replacement = [{ id: '1', type: 'replace', item }]
const replaced = apply(replacement, [{ ...item, style: { width: 100, height: 40 } }])
const measured = apply([{ id: '1', type: 'dimensions', dimensions: { width: 200, height: 100 } }], replaced)
console.log(JSON.stringify({ retained: replacement[0].item.measured, accepted: measured[0].measured, retainedItemUnchanged: replacement[0].item === item }, null, 2))
